const leads = [
  {lead_id:'lead-001', name:'Alex', email:' Alex@Cedar.example '},
  {lead_id:'lead-002', name:'Alex duplicate', email:'alex@cedar.example'},
  {lead_id:'lead-003', name:'Morgan', email:''},
  {lead_id:'lead-004', name:'Sam', email:'not-an-email'},
  {lead_id:'lead-005', name:'Taylor', email:'taylor@cedar.example'}
];
return leads.map(json => ({json}));

const seen = new Set();
return $input.all().map((item, index) => {
  const raw = item.json.email;
  const email = typeof raw === 'string' ? raw.trim().toLowerCase() : '';
  let status = 'ready';
  let reason = 'first_valid_email_in_batch';
  if (!email) { status = 'review'; reason = 'missing_email'; }
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    status = 'review'; reason = 'invalid_email_format';
  } else if (seen.has(email)) { status = 'duplicate'; reason = 'email_already_in_batch'; }
  else { seen.add(email); }
  return { json: {...item.json, original_email: raw ?? null, email, status, reason}, pairedItem: {item:index} };
});

const rows = $input.all().map(item => item.json);
const expected = ['ready','duplicate','review','review','ready'];
if (rows.length !== expected.length) throw new Error('Expected 5 demo records');
rows.forEach((row, i) => {
  if (row.status !== expected[i]) throw new Error('Wrong status for demo record ' + (i + 1));
});
if (rows[0].email !== 'alex@cedar.example') throw new Error('Normalization failed');
if (rows[2].reason !== 'missing_email' || rows[3].reason !== 'invalid_email_format') throw new Error('Review checks failed');
return [{json:{test_result:'PASS', input_records:rows.length, ready:rows.filter(r=>r.status==='ready').length, duplicates:rows.filter(r=>r.status==='duplicate').length, review:rows.filter(r=>r.status==='review').length, scope:'Current batch only. No CRM writes or persistent duplicate history.', records:rows}}];
